// Generates supabase/seed.sql from src/data.js so the cloud database starts
// with the same vehicles, settings, coupons and add-on prices as the demo.
// Usage: node scripts/make-seed.mjs
import { writeFileSync } from 'node:fs';
import { INITIAL_VEHICLES, DEFAULT_SETTINGS, DEFAULT_COUPONS, ADDONS } from '../src/data.js';

const q = (s) => `'${String(s).replace(/'/g, "''")}'`;
const j = (o) => `${q(JSON.stringify(o))}::jsonb`;

const { lineChannelToken, ...publicSettings } = DEFAULT_SETTINGS; // never store secrets in public settings

const lines = [
  '-- Generated by scripts/make-seed.mjs — run after schema.sql (safe to re-run; existing rows are kept)',
  ...INITIAL_VEHICLES.map((v, i) => `insert into public.vehicles (id, data, sort_order) values (${q(v.id)}, ${j(v)}, ${i}) on conflict (id) do nothing;`),
  `insert into public.settings (id, data) values (1, ${j(publicSettings)}) on conflict (id) do nothing;`,
  ...DEFAULT_COUPONS.map((c) => `insert into public.coupons (code, percent, active, label, only_category) values (${q(c.code)}, ${c.percent}, ${c.active}, ${q(c.label)}, ${c.onlyCategory ? q(c.onlyCategory) : 'null'}) on conflict (code) do nothing;`),
  ...ADDONS.map((a) => `insert into public.addon_prices (id, price, unit, trips, only_for) values (${q(a.id)}, ${a.price}, ${q(a.unit)}, ${a.trips || 1}, ${a.onlyFor ? q(a.onlyFor) : 'null'}) on conflict (id) do update set price = excluded.price, unit = excluded.unit, trips = excluded.trips, only_for = excluded.only_for;`),
  '',
];
writeFileSync(new URL('../supabase/seed.sql', import.meta.url), lines.join('\n'));
console.log(`seed.sql: ${INITIAL_VEHICLES.length} vehicles, ${DEFAULT_COUPONS.length} coupons, ${ADDONS.length} add-ons`);
